#!/usr/bin/env python3
"""Regenerate docs/CURRICULUM.md from content/ (worlds, lessons, tasks, XP):   python3 tools/make_curriculum.py"""
import os
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
os.environ.setdefault("POLYCAMP_DATA", tempfile.mkdtemp(prefix="pc-cur-"))
sys.path.insert(0, str(ROOT / "server"))
import lessons  # noqa: E402

c = lessons.Content()
out = ["# Curriculum", "",
       "Generated by `tools/make_curriculum.py`. %d worlds, %d lessons, %d XP in total. Each lesson ends with checked tasks; "
       "bosses close each world." % (len(c.worlds), len(c.lessons), c.total_xp()), ""]
for w in c.worlds:
    out += ["## World %d: %s" % (w.order, w.title), "", "*%s* Project: %s." % (w.tagline, w.project), "",
            "| # | Lesson | Min | Tasks | XP | Starts from |", "| --- | --- | --- | --- | --- | --- |"]
    for i, lid in enumerate(w.lessons, 1):
        l = c.lessons[lid]
        out.append("| %d | %s%s | %d | %d | %d | %s |" % (i, "**BOSS** " if l.boss else "", l.title, l.minutes, len(l.tasks()), l.total_xp(), l.scene))
    out.append("")
(ROOT / "docs" / "CURRICULUM.md").write_text("\n".join(out))
print("wrote docs/CURRICULUM.md")
